from pysat.pb import PBEnc
from pysat.solvers import Solver
from pysat.formula import CNF

# Let's use a direct backtracking approach with the constraints
# seq[i] = v means position i (0-indexed) has value v
# For each value v, if it appears at position i, it must also appear at position i+v+1

# Fixed assignments (converting to 0-indexed):
# seq[5]=14, seq[9]=4, seq[11]=15, seq[21]=9, seq[26]=13, seq[29]=10
fixed = {5: 14, 9: 4, 11: 15, 21: 9, 26: 13, 29: 10}

def solve_langford():
    n = 16
    seq = [0] * 32  # 0 means unassigned

    # Apply fixed assignments
    for pos, val in fixed.items():
        seq[pos] = val

    # Track which values are placed and where
    placed = {}  # val -> [positions]

    for pos, val in fixed.items():
        if val not in placed:
            placed[val] = []
        placed[val].append(pos)

    # Check consistency of fixed assignments
    for val, positions in placed.items():
        if len(positions) == 2:
            if abs(positions[1] - positions[0]) != val + 1:
                print(f"Inconsistency: value {val} at positions {positions}")
                return None
        elif len(positions) == 1:
            pos = positions[0]
            # The other occurrence must be at pos - (val+1) or pos + (val+1)
            other1 = pos - (val + 1)
            other2 = pos + (val + 1)
            valid = []
            if 0 <= other1 < 32:
                valid.append(other1)
            if 0 <= other2 < 32:
                valid.append(other2)
            if not valid:
                print(f"No valid position for second occurrence of {val}")
                return None

    print("Fixed assignments check passed")
    print("Placed so far:", placed)

    # Use backtracking
    def backtrack(seq, placed, remaining_vals):
        # Find next unassigned position
        pos = -1
        for i in range(32):
            if seq[i] == 0:
                pos = i
                break

        if pos == -1:
            # Check all values placed exactly twice
            return all(len(placed.get(v, [])) == 2 for v in range(1, n+1))

        # Try placing values at this position
        for val in sorted(remaining_vals):
            count = len(placed.get(val, []))

            if count == 0:
                # First occurrence - try placing here, second at pos + val + 1
                other = pos + val + 1
                if other < 32 and seq[other] == 0:
                    seq[pos] = val
                    seq[other] = val
                    placed[val] = [pos, other]
                    new_remaining = remaining_vals - {val}
                    if backtrack(seq, placed, new_remaining):
                        return True
                    seq[pos] = 0
                    seq[other] = 0
                    del placed[val]

            elif count == 1:
                # Second occurrence - check if this position is valid
                first_pos = placed[val][0]
                if abs(pos - first_pos) == val + 1:
                    seq[pos] = val
                    placed[val].append(pos)
                    new_remaining = remaining_vals - {val}
                    if backtrack(seq, placed, new_remaining):
                        return True
                    seq[pos] = 0
                    placed[val].pop()

        return False

    # Determine remaining values to place
    remaining = set(range(1, n+1))
    for val, positions in placed.items():
        if len(positions) == 2:
            remaining.discard(val)

    # For values with one position fixed, we need to handle them specially
    # Let's pre-place the second occurrence of fixed single values
    for val, positions in list(placed.items()):
        if len(positions) == 1:
            pos = positions[0]
            other1 = pos - (val + 1)
            other2 = pos + (val + 1)
            # Check which is valid
            valid_others = []
            if 0 <= other1 < 32 and seq[other1] == 0:
                valid_others.append(other1)
            if 0 <= other2 < 32 and seq[other2] == 0:
                valid_others.append(other2)
            print(f"Value {val} at pos {pos}, possible second positions: {valid_others}")

    print("\nStarting backtrack...")
    print("Sequence so far:", seq)
    print("Remaining values:", sorted(remaining))

    if backtrack(seq, placed, remaining):
        return seq
    return None

result = solve_langford()
if result:
    print("\nSolution found:", result)
    # Verify
    for v in range(1, 17):
        positions = [i for i, x in enumerate(result) if x == v]
        assert len(positions) == 2, f"Value {v} appears {len(positions)} times"
        assert positions[1] - positions[0] == v + 1, f"Value {v} at {positions}, diff={positions[1]-positions[0]}, expected {v+1}"
    print("Verification passed!")
    # Check fixed assignments
    for pos, val in fixed.items():
        assert result[pos] == val, f"Fixed assignment violated: seq[{pos}]={result[pos]}, expected {val}"
    print("Fixed assignments verified!")
else:
    print("No solution found")

